import { RenderPlugin } from "@11ty/eleventy";



export default function (eleventyConfig) {


  // Serve the real component sources and the manifest from the site
  eleventyConfig.addPassthroughCopy({ src: "src" });
  eleventyConfig.addPassthroughCopy({ "custom-elements.json": "custom-elements.json" });
  // Copy the stylesheets (paths relative to the project root) and rebuild when they change
  eleventyConfig.addPassthroughCopy("docs/*.css", { mode: "html-relative" });
  eleventyConfig.addWatchTarget("docs/*.css");
  // Import map and packages generated by nudeps (see nudeps.js)
  eleventyConfig.addPassthroughCopy({ "docs/importmap.js": "importmap.js" });
  eleventyConfig.addPassthroughCopy({ "docs/client_modules": "client_modules" });
  // Packages may ship README.md or similar; don't render them as templates
  eleventyConfig.ignores.add("docs/client_modules/**");
	eleventyConfig.addPlugin(RenderPlugin);
  eleventyConfig.addWatchTarget("src/");
  eleventyConfig.addWatchTarget("custom-elements.json");

  return {
    dir: { input: "docs", output: "_site", includes: "_includes", data: "_data" },
    pathPrefix: "/g12n-time/", // repo name on GitHub Pages
    markdownTemplateEngine: "njk",
  };
}
